{{{
oval_param_in_file_variable_test(
    filepath=login_defs_path,
    parameter="CREATE_HOME",
    pattern="^[\s]*(?i)CREATE_HOME(?-i)[\s]+(yes)",
    regex_capture="CREATE_HOME\s+(yes)",
    operation="pattern match",
    type="string",
    test_id="test_accounts_have_homedir_login_defs",
    variable="var_accounts_have_homedir_login_defs"
)
}}}

{{% set login_defs_drop_in_config_dir = "/".join(login_defs_drop_in_path.split("/")[:-1]) %}}
{{{
oval_param_in_file_variable_test(
    filepath=login_defs_drop_in_config_dir,
    filename_regex=".*\.defs$",
    parameter="CREATE_HOME",
    pattern="^[\s]*(?i)CREATE_HOME(?-i)[\s]+(yes)",
    regex_capture="CREATE_HOME\s+(yes)",
    operation="pattern match",
    type="string",
    test_id="test_accounts_have_homedir_login_defs_drop_in_path",
    variable="var_accounts_have_homedir_login_defs"
)
}}}






    {{{ login_defs_drop_in_config_dir }}}
